// TECH — executed in an isolated profile-test checkout; importing these helpers composes the real driver.
import {interactive,KEY,sleep} from "../helpers/interactive";
import {workspace,cli} from "../helpers/env";
import {ScriptedProvider} from "../helpers/scripted-provider";
import {readFileSync} from "node:fs";import{join}from"node:path";
function check(value:unknown,message:string):asserts value{if(!value)throw Error(message);}
const ws=workspace(),provider=new ScriptedProvider([]),run=interactive([],ws,{provider,userConfig:{ui:{companion:{enabled:true}}}});
try{await run.idle();run.type("/companion");run.type(KEY.enter);await run.waitFor(text=>text.includes("Nom proposé :"));await sleep(380);run.type("o");await run.waitFor(text=>text.includes("Compagnon éclos :"));const soul=JSON.parse(readFileSync(join(ws.configHome,"config.json"),"utf8")).ui.companion.soul;check(soul.name&&soul.personality,"Soul was not stored");check(provider.requests.length===0,"A model was called for decoration");run.type(KEY.ctrlC);run.type(KEY.ctrlC);await run.done;}finally{if(!run.finished()){run.type(KEY.escape);run.type(KEY.ctrlC);run.type(KEY.ctrlC);await run.done;}}
const blocked=workspace();blocked.write("managed/policy.json",JSON.stringify({ui:{companion:{enabled:false}}}));const hidden=interactive([],blocked,{provider:new ScriptedProvider([]),userConfig:{ui:{companion:{enabled:true,soul:{name:"HIDDEN_COMPANION",personality:"patient"}}}}});try{await hidden.idle();hidden.type("/companion");hidden.type(KEY.enter);await hidden.waitFor(text=>text.includes("Commande inconnue"));check(!hidden.all().join("\n").includes("HIDDEN_COMPANION"),"Managed disabled companion rendered");hidden.type(KEY.ctrlC);hidden.type(KEY.ctrlC);await hidden.done;}finally{if(!hidden.finished()){hidden.type(KEY.ctrlC);hidden.type(KEY.ctrlC);await hidden.done;}}
const rescue=workspace();rescue.write("home/config/presence/frozen-probe.json",JSON.stringify({sessionId:"frozen-probe",pid:process.pid,cwd:rescue.project,heartbeat:new Date(Date.now()-600000).toISOString()}));const result=await cli(["--non-interactive","/session-rescue"],rescue,{provider:new ScriptedProvider([])});check(result.code===0,"Session rescue command failed");check(result.stdout.includes("frozen-probe")&&result.stdout.includes("figée présumée"),"Frozen process missing from report");console.log("COMPANION_AND_RESCUE_PROBE_PASSED");
